import { Pool, PoolClient } from "pg";

export interface Migration {
  version: number;
  name: string;
  up(tx: PoolClient): Promise<void>;
}

export async function migrate(pool: Pool, all: Migration[]): Promise<number> {
  const client = await pool.connect();
  try {
    await client.query(
      `CREATE TABLE IF NOT EXISTS iam_schema_version (
         version integer PRIMARY KEY,
         name text NOT NULL,
         applied_at timestamptz NOT NULL DEFAULT now()
       )`,
    );
    await client.query("SELECT pg_advisory_lock(hashtext('iam_schema_version'))");
    try {
      const { rows } = await client.query<{ max: number | null }>(
        "SELECT max(version) AS max FROM iam_schema_version",
      );
      const current = rows[0].max ?? 0;
      const pending = all.filter((m) => m.version > current).sort((a, b) => a.version - b.version);

      for (const m of pending) {
        await client.query("INSERT INTO iam_schema_version (version, name) VALUES ($1, $2)", [
          m.version,
          m.name,
        ]);
        await client.query("BEGIN");
        try {
          await m.up(client);
          await client.query("COMMIT");
        } catch (err) {
          await client.query("ROLLBACK");
          throw new Error(`IAM migration ${m.version} (${m.name}) failed`, { cause: err });
        }
      }
      return pending.length;
    } finally {
      await client.query("SELECT pg_advisory_unlock(hashtext('iam_schema_version'))");
    }
  } finally {
    client.release();
  }
}

import { Migration } from "./migrate";

export const iamMigrations: Migration[] = [
  {
    version: 41,
    name: "role_bindings_add_scope",
    async up(tx) {
      await tx.query("ALTER TABLE role_bindings ADD COLUMN scope text");
      await tx.query("UPDATE role_bindings SET scope = 'org' WHERE scope IS NULL");
      await tx.query("ALTER TABLE role_bindings ALTER COLUMN scope SET NOT NULL");
      await tx.query("ALTER TABLE role_bindings ALTER COLUMN scope SET DEFAULT 'org'");
    },
  },
  {
    version: 42,
    name: "role_bindings_unique_per_scope",
    async up(tx) {
      await tx.query(
        `DELETE FROM role_bindings a USING role_bindings b
          WHERE a.principal_id = b.principal_id
            AND a.role_id = b.role_id
            AND a.scope = b.scope
            AND a.id > b.id`,
      );
      await tx.query(
        "ALTER TABLE role_bindings ADD CONSTRAINT role_bindings_principal_role_scope_key UNIQUE (principal_id, role_id, scope)",
      );
    },
  },
  {
    version: 43,
    name: "api_keys_add_last_used",
    async up(tx) {
      await tx.query("ALTER TABLE api_keys ADD COLUMN last_used_at timestamptz");
      await tx.query("CREATE INDEX api_keys_last_used_idx ON api_keys (last_used_at)");
    },
  },
];

import { Pool } from "pg";
import { migrate } from "./migrate";
import { iamMigrations } from "./iamMigrations";

export async function bootIdentityService(pool: Pool, startHttp: () => Promise<void>) {
  try {
    const applied = await migrate(pool, iamMigrations);
    console.log(JSON.stringify({ msg: "iam schema up to date", applied }));
  } catch (err) {
    console.error(JSON.stringify({ msg: "iam migration failed", error: String(err) }));
    process.exitCode = 1;
    return;
  }
  await startHttp();
}

